-- AQU-265: AI budget counters (0034_ai_usage_daily.sql)
CREATE TABLE IF NOT EXISTS ai_usage_daily (
  user_id       INTEGER     NOT NULL,
  date_utc      DATE        NOT NULL,
  request_count INTEGER     NOT NULL DEFAULT 0,
  PRIMARY KEY (user_id, date_utc)
);
CREATE INDEX IF NOT EXISTS idx_ai_usage_daily_date ON ai_usage_daily(date_utc);

-- OmniVoice TTS usage metering (0041_tts_usage_daily.sql).
-- Per-user, org-attributed audio-seconds. (user_id=0, org_id=0) = global sentinel.
-- Org totals derived at read time: SUM WHERE org_id = ?
CREATE TABLE IF NOT EXISTS tts_usage_daily (
  user_id       INTEGER          NOT NULL,
  org_id        INTEGER          NOT NULL,
  date_utc      DATE             NOT NULL,
  request_count INTEGER          NOT NULL DEFAULT 0,
  audio_seconds DOUBLE PRECISION NOT NULL DEFAULT 0,
  PRIMARY KEY (user_id, org_id, date_utc)
);
CREATE INDEX IF NOT EXISTS idx_tts_usage_org_date ON tts_usage_daily (org_id, date_utc);

-- Org credits & unified compute-cost model (0042_org_credit_usage_daily.sql).
-- Cross-rail cost rollup; rail = 'llm' | 'agent' | 'tts'. raw_cost_cents = actual
-- infra cost; credits derived on read. Existing usage tables unchanged.
CREATE TABLE IF NOT EXISTS org_credit_usage_daily (
  org_id         INTEGER          NOT NULL,
  user_id        INTEGER          NOT NULL,
  date_utc       DATE             NOT NULL,
  rail           TEXT             NOT NULL,
  raw_cost_cents DOUBLE PRECISION NOT NULL DEFAULT 0,
  units          INTEGER          NOT NULL DEFAULT 0,
  PRIMARY KEY (org_id, user_id, date_utc, rail)
);
CREATE INDEX IF NOT EXISTS idx_org_credit_org_date ON org_credit_usage_daily (org_id, date_utc);

-- Translation agent run ledger (0040_agent_runs.sql). One row per
-- POST /api/v1/ai/agent/run; staged commits carry payload.agent_run_id →
-- run_id for attribution / undo-run / cost rollups.
CREATE TABLE IF NOT EXISTS agent_runs (
    run_id      TEXT PRIMARY KEY,
    project_id  TEXT NOT NULL,
    user_id     BIGINT NOT NULL,
    username    TEXT NOT NULL,
    prompt      TEXT NOT NULL,
    model       TEXT NOT NULL,
    status      TEXT NOT NULL DEFAULT 'running', -- running|ok|capped|error
    prompt_tokens     BIGINT NOT NULL DEFAULT 0,
    completion_tokens BIGINT NOT NULL DEFAULT 0,
    cost_cents  DOUBLE PRECISION NOT NULL DEFAULT 0,
    steps       INTEGER NOT NULL DEFAULT 0,
    session_id  TEXT,                            -- 0050: owning agent_sessions row (nullable)
    staged_count INTEGER NOT NULL DEFAULT 0,     -- 0051: target.cell.commit events staged by the run
    started_at  BIGINT NOT NULL,
    ended_at    BIGINT
);
CREATE INDEX IF NOT EXISTS idx_agent_runs_project ON agent_runs (project_id, started_at DESC);

-- Agent sessions (0050_agent_sessions.sql): server-persisted conversations for
-- the translation agent. convo = JSON array of stored messages (user/assistant/
-- tool — the system prompt is rebuilt per run). Session ids are client-generated
-- UUIDs; ownership is (project_id, user_id), enforced on load.
CREATE TABLE IF NOT EXISTS agent_sessions (
    session_id TEXT PRIMARY KEY,
    project_id TEXT NOT NULL,
    user_id    BIGINT NOT NULL,
    title      TEXT NOT NULL DEFAULT '',
    convo      TEXT NOT NULL DEFAULT '[]',
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_agent_sessions_project_user
    ON agent_sessions (project_id, user_id, updated_at DESC);

-- Model A/B testing (0048_model_ab_events.sql). One row per default-model chat
-- request while a platform experiment (platform_settings.abTest) is enabled;
-- arm = champion (defaultLlmModel) | challenger. The SPA reports the user's
-- gesture on the AI output (accepted = cell validated, edited = human commit
-- overwrote the draft) via POST /chat/ab-feedback keyed by the id returned in
-- the X-AB-Request-Id response header. Aggregated by GET /admin/ab-results.
CREATE TABLE IF NOT EXISTS model_ab_events (
    id         TEXT PRIMARY KEY,
    user_id    BIGINT NOT NULL,
    arm        TEXT NOT NULL,                 -- 'champion' | 'challenger'
    model      TEXT NOT NULL,
    source     TEXT NOT NULL DEFAULT 'chat',
    error      INTEGER NOT NULL DEFAULT 0,    -- 1 = upstream request failed
    latency_ms INTEGER,
    outcome    TEXT,                          -- 'accepted' | 'edited' | 'rejected'
    -- 0049: normalized Levenshtein [0,1] between the AI draft and the human's
    -- text — 0 = accepted verbatim. Outcome is first-write-wins; the distance
    -- refines with further edits (last write wins).
    edit_distance DOUBLE PRECISION,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    outcome_at TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_model_ab_events_created ON model_ab_events(created_at);
CREATE INDEX IF NOT EXISTS idx_model_ab_events_user ON model_ab_events(user_id);

-- Lane-scoped reviewer permissions (0059_project_member_scopes.sql, AQU-553).
-- ADDITIVE restrictions on a member's role floor. No rows for a (project,user)
-- pair = unscoped = today's behavior. 'lane' rows restrict target-side writes
-- to those lanes (default lane stored as literal ''); 'file' rows restrict
-- writes to those fileIds. Kinds compose with AND. Enforced in sync-worker
-- authorize; source/comment/audio/file-level events are never gated. Leads
-- (role >= 500) must stay unscoped (auth-worker CRUD rejects scoping them).
CREATE TABLE IF NOT EXISTS project_member_scopes (
    project_id TEXT NOT NULL,
    user_id    BIGINT NOT NULL,
    kind       TEXT NOT NULL CHECK (kind IN ('lane','file')),
    value      TEXT NOT NULL,
    created_by TEXT,
    created_at BIGINT NOT NULL,
    PRIMARY KEY (project_id, user_id, kind, value)
);

-- AQU-533 Agent API: immutable changeset execution plans (0055). External
-- callers submit domain commands; prepare compiles them into a staged plan
-- with server-computed preconditions, effect summary, and content digest.
-- Commit re-checks preconditions (plan_stale on drift), routes compiled events
-- through the existing /events perimeter, and records an execution receipt.
CREATE TABLE IF NOT EXISTS changesets (
    id                 TEXT PRIMARY KEY,          -- client-supplied UUIDv7
    project_id         TEXT NOT NULL,
    created_by_user_id TEXT NOT NULL,             -- the credential's owning user
    credential_id      TEXT NOT NULL,
    autonomy_mode      TEXT NOT NULL CHECK (autonomy_mode IN ('ask', 'act')),
    status             TEXT NOT NULL DEFAULT 'staged'
                         CHECK (status IN ('staged', 'committing', 'committed', 'discarded', 'stale', 'expired')),
    commands           JSONB NOT NULL,            -- normalized domain commands
    preconditions      JSONB NOT NULL,            -- per-cell head/source pins resolved at prepare
    summary            JSONB NOT NULL,            -- server-computed effect summary
    digest             TEXT NOT NULL,             -- SHA-256 over canonical(commands + preconditions)
    receipt            JSONB,                     -- execution receipt (after commit)
    confirmation_id    TEXT,                      -- consumed ask-mode approval (after commit)
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at         TIMESTAMPTZ NOT NULL,
    committed_at       TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_changesets_project_status ON changesets(project_id, status);

-- One-time human approval assertions for ask-mode commits (AQU-533 §3). A row
-- binds a specific changeset digest + credential; commit consumes it exactly
-- once (UPDATE ... SET consumed_at WHERE consumed_at IS NULL RETURNING).
CREATE TABLE IF NOT EXISTS changeset_confirmations (
    id            TEXT PRIMARY KEY,               -- UUIDv7
    changeset_id  TEXT NOT NULL,
    user_id       TEXT NOT NULL,                  -- approving human (browser session)
    credential_id TEXT NOT NULL,
    digest        TEXT NOT NULL,                  -- must match the changeset digest at commit
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at    TIMESTAMPTZ NOT NULL,
    consumed_at   TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_changeset_confirmations_changeset
  ON changeset_confirmations(changeset_id);

-- External API credentials (0054_api_credentials.sql): personal access tokens
-- for the Agent API (AQU-533 §2). Per-user, optionally scoped to an org and/or
-- project, with an autonomy ceiling ('ask' | 'act'). Only a SHA-256 hash is
-- stored; token_prefix (first 12 chars, incl. the 'aqk_' tag) is display-only.
-- User-scoped like agent_sessions; live role is re-resolved per call.
CREATE TABLE IF NOT EXISTS api_credentials (
    id           UUID PRIMARY KEY,
    user_id      TEXT NOT NULL,
    name         TEXT NOT NULL,
    token_prefix TEXT NOT NULL,
    token_hash   TEXT NOT NULL UNIQUE,
    mode         TEXT NOT NULL CHECK (mode IN ('ask', 'act')),
    org_id       TEXT,
    project_id   TEXT,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at   TIMESTAMPTZ,
    last_used_at TIMESTAMPTZ,
    revoked_at   TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_api_credentials_user ON api_credentials(user_id);
CREATE INDEX IF NOT EXISTS idx_api_credentials_token_hash ON api_credentials(token_hash);

-- Uploaded source artifacts (0056_artifacts.sql): agent-uploaded original files
-- (USFM, JSON, XLIFF, …) preserved verbatim in R2 for round-trip fidelity and
-- format inspection (AQU-533 §5). Bytes live in SNAPSHOTS under
-- `{prefix}artifacts/{projectId}/{artifactId}`; this row is metadata +
-- provenance + integrity digest. `file_id` is linked when a PlanImport
-- changeset referencing the artifact commits.
--
-- 0064_artifacts_audio.sql (Agent API v1.1 §3, W2-B): `kind` distinguishes a
-- verbatim source artifact ('source') from an uploaded audio clip ('audio').
-- Audio bytes are stored in the EXISTING per-file audio R2 layout used by
-- audio.ts (`{prefix}projects/{projectId}/files/{artifactId}/audio/{audio_id}`)
-- so a LinkMedia commit can serve them through the app's native /audio route;
-- `audio_id` is the full object name (`<artifactId>.<ext>`) the audio layout +
-- the cell.audio.attach payload expect.
CREATE TABLE IF NOT EXISTS artifacts (
    id                  UUID PRIMARY KEY,
    project_id          TEXT NOT NULL,
    uploaded_by_user_id TEXT NOT NULL,
    credential_id       TEXT NOT NULL,
    name                TEXT NOT NULL,
    content_type        TEXT,
    size_bytes          BIGINT NOT NULL,
    sha256              TEXT NOT NULL,
    r2_key              TEXT NOT NULL,
    file_id             TEXT,
    kind                TEXT NOT NULL DEFAULT 'source',
    audio_id            TEXT,
    -- AQU-635: format inspection/classification facts that belong to the
    -- immutable artifact rather than any one file interpretation.
    metadata            JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (id, project_id)
);
CREATE INDEX IF NOT EXISTS idx_artifacts_project ON artifacts(project_id);

-- AQU-635: one immutable artifact can contribute multiple package members or
-- files. Per-cell reversible locators remain in cells.metadata; this relation
-- stores only file-level interpretation/provenance and compact manifests.
CREATE TABLE IF NOT EXISTS artifact_bindings (
    id              UUID PRIMARY KEY,
    project_id      TEXT NOT NULL,
    artifact_id     UUID NOT NULL,
    file_id         TEXT NOT NULL,
    binding_role    TEXT NOT NULL
                      CHECK (binding_role IN ('source', 'target', 'support', 'roundtrip-output')),
    target_lang     TEXT NOT NULL DEFAULT '',
    member_path     TEXT NOT NULL DEFAULT '',
    profile_id      TEXT NOT NULL,
    profile_version TEXT NOT NULL,
    fidelity        TEXT NOT NULL
                      CHECK (fidelity IN ('native', 'verified-recipe', 'content-only', 'preserved-only')),
    manifest        JSONB NOT NULL DEFAULT '{}'::jsonb,
    recipe          JSONB,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (artifact_id, file_id, binding_role, target_lang, member_path),
    CONSTRAINT artifact_bindings_artifact_project_fkey
      FOREIGN KEY (artifact_id, project_id)
      REFERENCES artifacts(id, project_id)
      ON DELETE CASCADE,
    CONSTRAINT artifact_bindings_file_project_fkey
      FOREIGN KEY (file_id, project_id)
      REFERENCES files(id, project_id)
      ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_artifact_bindings_project_file
  ON artifact_bindings(project_id, file_id);
CREATE INDEX IF NOT EXISTS idx_artifact_bindings_artifact
  ON artifact_bindings(artifact_id);

